function allFullTrees(n: number): TreeNode[] {
  if (n % 2 === 0) return [];
  if (n === 1) return [new TreeNode(0)];
  const out: TreeNode[] = [];
  for (let i = 1; i < n; i += 2) {
    for (const left of allFullTrees(i)) {
      for (const right of allFullTrees(n - 1 - i)) out.push(new TreeNode(0, left, right));
    }
  }
  return out;
}

