function allFullTrees(n: number): TreeNode[] {
  const memo = new Map<number, TreeNode[]>();
  const build = (size: number): TreeNode[] => {
    if (size % 2 === 0) return [];
    if (size === 1) return [new TreeNode(0)];
    if (memo.has(size)) return memo.get(size)!;
    const out: TreeNode[] = [];
    for (let i = 1; i < size; i += 2) {
      const lefts = build(i), rights = build(size - 1 - i);
      for (const left of lefts) for (const right of rights) out.push(new TreeNode(0, left, right));
    }
    memo.set(size, out);
    return out;
  };
  return build(n);
}

